<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Services\Dezerx\Palworld\PalworldMods; use Pterodactyl\Services\Dezerx\Palworld\PalworldCatalogue; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonDeleteRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonToggleRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonInstallRequest; class PalworldModController extends ClientApiController { private const MAX_NAME = 255; private const ARCHIVE = '.zip'; public function __construct(private readonly PalworldCatalogue $catalogue) { parent::__construct(); } public function search(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'query' => ['nullable', 'string', 'max:100'], 'page' => ['nullable', 'integer', 'min:1', 'max:100'], ]); return new JsonResponse($this->catalogue->search( trim((string) ($data['query'] ?? '')), (int) ($data['page'] ?? 1), )); } public function versions(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate(['mod' => ['required', 'string', 'max:32']]); return new JsonResponse(['files' => $this->catalogue->files($data['mod'])]); } public function index(AddonRequest $request, Server $server): JsonResponse { $directory = PalworldMods::directory(); $entries = $this->files($server)->listFiles($directory); if ($entries === null) { return new JsonResponse([ 'available' => false, 'directory' => $directory, 'extensions' => PalworldMods::extensions(), 'mods' => [], ]); } $mods = []; foreach ($entries as $entry) { $name = (string) ($entry['name'] ?? ''); if (($entry['directory'] ?? false) === true || !PalworldMods::isMod($name)) { continue; } $disabled = str_ends_with(mb_strtolower($name), PalworldMods::DISABLED_SUFFIX); $bare = $disabled ? mb_substr($name, 0, -mb_strlen(PalworldMods::DISABLED_SUFFIX)) : $name; $mods[] = [ 'file' => $name, 'name' => $this->readableName($name, $disabled), 'size' => (int) ($entry['size'] ?? 0), 'modifiedAt' => $entry['modified_at'] ?? null, 'disabled' => $disabled, 'archive' => str_ends_with(mb_strtolower($bare), self::ARCHIVE), ]; } usort($mods, fn (array $a, array $b) => strcasecmp($a['name'], $b['name'])); return new JsonResponse([ 'available' => true, 'directory' => $directory, 'extensions' => PalworldMods::extensions(), 'mods' => $mods, ]); } public function install(AddonInstallRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'mod' => ['required', 'string', 'max:32'], 'file' => ['required', 'string', 'max:32'], ]); if (!$this->catalogue->configured()) { return new JsonResponse(['errors' => [[ 'code' => 'CurseforgeUnconfigured', 'detail' => 'This panel has no CurseForge API key, so the catalogue cannot be used. Ask an administrator to add one on the Palworld Mod Manager addon.', ]]], 422); } $url = $this->catalogue->downloadUrl($data['mod'], $data['file']); if ($url === null) { return new JsonResponse(['errors' => [[ 'code' => 'NoDownloadUrl', 'detail' => 'CurseForge would not give a download link for that file. The author may have turned off third-party downloads — get it from its CurseForge page and upload it with the file manager instead.', ]]], 422); } $filename = PalworldMods::safeName((string) $this->catalogue->filename($data['mod'], $data['file'])); if ($filename === null) { return new JsonResponse(['errors' => [[ 'code' => 'NotAMod', 'detail' => 'That file is not one this tab manages: it does not end in ' . implode(', ', PalworldMods::extensions()) . '.', ]]], 422); } $files = $this->files($server); $directory = PalworldMods::directory(); $files->createDirectory($directory); if (!$files->pullFile($directory, $url, $filename)) { return new JsonResponse(['errors' => [[ 'code' => 'DownloadFailed', 'detail' => 'The node could not fetch that file from CurseForge.', ]]], 502); } Activity::event('server:palworld-mod.install') ->subject($server) ->property(['file' => $filename, 'curseforge' => $data['mod'], 'version' => $data['file']]) ->log(); return new JsonResponse([ 'file' => $filename, 'archive' => str_ends_with(mb_strtolower($filename), self::ARCHIVE), ]); } public function toggle(AddonToggleRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:' . self::MAX_NAME]]); $from = PalworldMods::safeName($data['file']); if ($from === null) { return $this->notAMod(); } $to = str_ends_with(mb_strtolower($from), PalworldMods::DISABLED_SUFFIX) ? mb_substr($from, 0, -mb_strlen(PalworldMods::DISABLED_SUFFIX)) : $from . PalworldMods::DISABLED_SUFFIX; if (!$this->files($server)->renamePath(PalworldMods::directory(), $from, $to)) { return new JsonResponse(['errors' => [[ 'code' => 'RenameFailed', 'detail' => 'That could not be changed.', ]]], 502); } Activity::event('server:palworld-mod.toggle') ->subject($server) ->property(['from' => $from, 'to' => $to]) ->log(); return new JsonResponse(['file' => $to]); } public function unpack(AddonInstallRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:' . self::MAX_NAME]]); $file = PalworldMods::safeName($data['file']); if ($file === null || !str_ends_with(mb_strtolower($file), self::ARCHIVE)) { return new JsonResponse(['errors' => [[ 'code' => 'NotAnArchive', 'detail' => 'Only a .zip sitting in the mod folder can be unpacked.', ]]], 422); } $files = $this->files($server); $directory = PalworldMods::directory(); if (!$files->decompress($directory, $file)) { return new JsonResponse(['errors' => [[ 'code' => 'UnpackFailed', 'detail' => 'The node could not unpack that archive. It may still be downloading — wait a moment and try again.', ]]], 502); } $files->deletePaths($directory, [$file]); Activity::event('server:palworld-mod.unpack') ->subject($server) ->property('file', $file) ->log(); return new JsonResponse(['file' => $file]); } public function destroy(AddonDeleteRequest $request, Server $server): JsonResponse { $data = $request->validate(['file' => ['required', 'string', 'max:' . self::MAX_NAME]]); $file = PalworldMods::safeName($data['file']); if ($file === null) { return $this->notAMod(); } if (!$this->files($server)->deletePaths(PalworldMods::directory(), [$file])) { return new JsonResponse(['errors' => [[ 'code' => 'DeleteFailed', 'detail' => 'That could not be removed.', ]]], 502); } Activity::event('server:palworld-mod.delete') ->subject($server) ->property('file', $file) ->log(); return new JsonResponse([], 204); } private function notAMod(): JsonResponse { return new JsonResponse(['errors' => [[ 'code' => 'NotAMod', 'detail' => 'That is not a file this tab manages.', ]]], 422); } private function readableName(string $file, bool $disabled): string { $name = $disabled ? mb_substr($file, 0, -mb_strlen(PalworldMods::DISABLED_SUFFIX)) : $file; foreach (PalworldMods::extensions() as $extension) { if (str_ends_with(mb_strtolower($name), $extension)) { $name = mb_substr($name, 0, -mb_strlen($extension)); break; } } return trim(preg_replace('/[\s_-]+/', ' ', $name) ?? $name) ?: $file; } private function files(Server $server): ServerFiles { return new ServerFiles($server); } } 